const familiasSinRespaldo = new Set(["REGISTRO DE AMBIENTE","ACCESORIOS","INSTRUMENTAL Y MEDICION AUXILIAR","INFORMATICA Y APOYO","COMPONENTES DE INCUBADORA","COMPONENTES DE MONITOREO","ALIMENTACION ELECTRICA","TRANSDUCTORES","FUENTES DE LUZ","DETECTORES RX","COMPRESORES AIRE","HUMIDIFICADORES"]);
const riesgoContextual = {"HELADERAS FREEZERS":5,"COMPONENTES DE INCUBADORA":4,"COMPONENTES DE MONITOREO":4,"ALIMENTACION ELECTRICA":4,"TRANSDUCTORES":4,"FUENTES DE LUZ":4,"SISTEMAS DE ASPIRACION":7,"DETECTORES RX":4,"COMPRESORES AIRE":5,"HUMIDIFICADORES":5};

export function obtenerRiesgoClinico(descripcion) {
  const nombre=normalizarIPA(descripcion);
  const exacto=ponderacionesEquipo.get(nombre);
  if (exacto) {
    return {valor:exacto[0],familia:exacto[1],origen:exacto[2],clase:exacto[3]};
  }
  const regla=patronesFuturos.find(r=>r.regex.test(nombre));
  if (regla) return {
    valor:regla.riesgo ?? riesgoContextual[regla.familia] ?? 5,
    familia:regla.familia, origen:"nuevo_por_regla",clase:regla.clase
  };
  return {valor:5, familia:nombre?"NUEVO EQUIPO POR REVISAR":"SIN DESCRIPCION",
    origen:"estimacion",clase:"indeterminado"};
}
export function obtenerCriticidadServicio(servicio, subservicio) {
  const s=normalizarIPA(servicio), u=normalizarIPA(subservicio);
  const especifico=ajustesSubservicio.get(s+"|"+u);
  if (especifico != null) return {valor:especifico, origen:"subservicio"};
  // El subservicio crítico se reconoce aun si aparece bajo otro servicio.
  if (/\b(UCIN|UCIP|UTIP|UCO|UTI|SHOCK ROOM|HEMODINAMIA|QUIROFANO|EMERGENCIA)\b/.test(u))
    return {valor:5,origen:"subservicio_estimado"};
  const exacto=ponderacionesServicio.get(s);
  if (exacto) return {valor:exacto[0],origen:exacto[1]};
  return {valor:3,origen:"servicio_sin_identificar"};
}
/** `respaldos` cuenta SOLO otros equipos con descripción exacta y servicio,
 * registrados como ACTIVO. Es un indicador aproximado de redundancia.
 * No incluye demanda, naturaleza de la falla, ni requiere datos clínicos extra.
 */
export function calcularIPA({descripcion,servicio,subservicio,respaldos}) {
  const equipo=obtenerRiesgoClinico(descripcion);
  const sector=obtenerCriticidadServicio(servicio,subservicio);
  const n=Number(respaldos);
  const aplicable=!familiasSinRespaldo.has(equipo.familia)&&equipo.clase!=="instalacion"
    &&equipo.clase!=="componente"&&equipo.clase!=="apoyo";
  const b=aplicable ? 10/(1+0.25*Math.max(0,Number.isFinite(n)?n:0)) : 0;
  if (!Number.isFinite(equipo.valor) || !Number.isFinite(sector.valor) || !Number.isFinite(b)) {
    throw new Error(`IPA: factores inválidos para ${descripcion} / ${servicio} / ${subservicio}`);
  }
  const valor=4.5*equipo.valor+4*sector.valor+3.5*b;
  if (!Number.isFinite(valor) || valor < 0 || valor > 100) {
    throw new Error(`IPA fuera de escala: ${valor} para ${descripcion}`);
  }
  const estimado=equipo.origen!=="base" || sector.origen==="servicio_sin_identificar"
    || sector.origen==="estimado" || equipo.clase==="indeterminado"
    || equipo.origen==="estimacion";
  return {
    valor:Number(Math.max(0,Math.min(100,valor)).toFixed(1)),
    factores:{riesgo_clinico:equipo.valor,servicio:sector.valor,
      falta_respaldo:Number(b.toFixed(2))},
    familia:equipo.familia,respaldos:aplicable?Math.max(0,Number.isFinite(n)?n:0):null,
    respaldo_aplicable:aplicable,origen_riesgo:equipo.origen,
    origen_servicio:sector.origen,estimado,version:"IPA-2"
  };
}
